import { test, expect } from '@playwright/test';

test.describe('Confirmation Modal for Record Deletion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display confirmation modal when user clicks delete button', async ({ page }) => {
    // Locate and click the delete button using getByRole
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmationModal).toBeVisible();

    // Verify modal title and message are displayed using getByText
    const modalTitle = page.getByText(/confirm deletion/i);
    await expect(modalTitle).toBeVisible();

    const modalMessage = page.getByText(/are you sure you want to delete this record/i);
    await expect(modalMessage).toBeVisible();

    // Verify confirmation button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Verify cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Verify delete button is disabled while modal is open
    await expect(deleteButton).toBeDisabled();
  });

  test('should close confirmation modal when user clicks cancel', async ({ page }) => {
    // Locate and click the delete button using getByRole
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation modal is visible
    const confirmationModal = page.getByRole('dialog', { name: /confirm deletion/i });
    await expect(confirmationModal).toBeVisible();

    // Verify cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Click cancel button using getByRole
    await cancelButton.click();

    // Verify confirmation modal is no longer visible
    await expect(confirmationModal).not.toBeVisible();

    // Verify delete button is enabled again
    await expect(deleteButton).not.toBeDisabled();
  });
});
